INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c8b8-7337-9546-9dd3c5332c75'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'A rectangular prism is made using 432 unit cubes. Its square base has side length greater than 3 units. Find the smallest possible height of the prism.', '3 units', 'If the square base side is s, then s²h = 432. Possible square factors of 432 with s > 3 are 16 (s=4, h=27), 36 (s=6, h=12), and 144 (s=12, h=3). The largest base area 144 yields the smallest height of 3 units.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.056Z'::timestamptz, '2026-08-15T07:50:40.056Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c8d5-7640-8b59-e05d2de930e3'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A laptop has a marked price of $m and is sold at a discount of d%. Express its selling price as a single fraction in terms of m and d.', 'm(100 - d)/100', 'The discount is md/100. Selling price = m - md/100 = m(100 - d)/100.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.085Z'::timestamptz, '2026-08-15T07:50:40.085Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c8e9-7526-a202-f1e78caca88b'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'A shop sells an item at the discounted price m(100 - d)/100 and makes a profit of 25%. Express the cost price as a single fraction in terms of m and d.', '4m(100 - d)/500', 'Selling price = 1.25 × cost price. Therefore, cost price = [m(100 - d)/100] ÷ 1.25 = 4m(100 - d)/500.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.105Z'::timestamptz, '2026-08-15T07:50:40.105Z'::timestamptz) ON CONFLICT (id) DO NOTHING;